function renderCockpit(){const d=data(),h=programHealth(),att=attentionItems(),streams=d.valueStreams||[];const heat=streams.map(s=>{const m=streamMaturity(s.id);return `<tr data-open-stream="${s.id}"><td><b>${s.id}</b> · ${esc(s.name)}<small>${esc(s.bpo||'TBD')}</small></td>${maturityCell(m.asis)}${maturityCell(m.ownership)}${maturityCell(m.requirements)}${maturityCell(m.tobe)}${maturityCell(m.fitgap)}${maturityCell(m.data)}${maturityCell(m.testing)}${maturityCell(m.readiness)}</tr>`}).join('');const openDec=(d.decisions||[]).filter(x=>!['Closed','Decided'].includes(x.status)).length,openRaid=(d.raid||[]).filter(x=>!['Closed','Resolved'].includes(x.status)).length;return `<div class="page-head"><div><h1>Executive Transformation Cockpit</h1><p>Program health, decisions, risks, workstream maturity and the next 90 days.</p></div>${badge(`Overall ${h.overall}`)}</div>
<div class="health-grid"><div class="health-card ${h.overall.toLowerCase()}"><span>Overall program</span><strong>${h.overall}</strong><small>system-derived from schedule, RAID and decisions</small></div><div class="health-card ${String(h.schedule).toLowerCase()}"><span>Schedule</span><strong>${h.schedule}</strong><small>${h.overdue} overdue · ${h.highOverdue} high priority</small></div><div class="health-card"><span>Scope</span><strong>${h.scope}</strong><small>open scope decisions drive amber status</small></div><div class="health-card"><span>Open RAID</span><strong>${openRaid}</strong><small>${h.critical} critical · ${h.high} high/critical</small></div><div class="health-card"><span>Open decisions</span><strong>${openDec}</strong><small>${h.overDec} overdue</small></div><div class="health-card"><span>Steering escalations</span><strong>${h.esc}</strong><small>open items requiring committee attention</small></div></div>
<div class="grid cockpit-main"><div><div class="section-title"><h2>Value-stream transformation maturity</h2><span>click any row to drill down</span></div><div class="card table-wrap heatmap"><table class="data-table matrix"><thead><tr><th>Value stream</th><th>As-Is</th><th>Ownership</th><th>Requirements</th><th>To-Be</th><th>Fit/Gap</th><th>Data</th><th>Testing</th><th>Readiness</th></tr></thead><tbody>${heat}</tbody></table></div></div><div><div class="section-title"><h2>Requires attention</h2><span>${att.length}</span></div><div class="card attention-panel">${att.length?att.map(x=>`<div class="attention-item ${x.tone}"><span>${esc(x.type)}</span><b>${esc(x.title)}</b><small>${esc(x.meta)}</small></div>`).join(''):'<div class="empty">No current escalations, overdue decisions or high-priority exceptions.</div>'}</div></div></div>
<div class="section-title"><h2>Enterprise value chain</h2><span>current operating backbone</span></div><div class="stream-strip">${streams.map(s=>{const m=streamMaturity(s.id);return `<button class="card stream-card" data-open-stream="${s.id}"><div class="num">0${s.number}</div><h3>${esc(s.name)}</h3><div class="bpo">${esc(s.bpo)}</div><div class="maturity-bar"><span style="width:${m.readiness}%"></span></div><small>${fmtPct(m.readiness)} transformation maturity</small></button>`}).join('')}</div><div class="cross-strip">${(d.crossFunctional||[]).map(s=>`<button class="card stream-card compact" data-open-stream="${s.id}"><div class="num">Cross-functional</div><h3>${esc(s.name)}</h3><div class="bpo">${esc(s.bpo)}</div>${badge(s.status)}</button>`).join('')}</div>
<div class="section-title"><h2>30 / 60 / 90 day outlook</h2><span>open dated work</span></div><div class="grid three-col outlook-grid">${outlookCard('Next 30 days',taskOutlook(0,30))}${outlookCard('31–60 days',taskOutlook(31,60))}${outlookCard('61–90 days',taskOutlook(61,90))}</div>`}
function outlookCard(title,items){return `<div class="card pad"><h3>${esc(title)}</h3>${items.slice(0,6).map(t=>`<div class="outlook-item"><b>${esc(t.title)}</b><small>${esc(t.stream)} · ${esc(t.owner)} · ${esc(t.forecastDue||t.due)}</small></div>`).join('')||'<div class="empty mini">No dated tasks in this window.</div>'}${items.length>6?`<small>+ ${items.length-6} more</small>`:''}</div>`}
function renderStreams(){const d=data(),s=allStreams().find(x=>x.id===selectedStream)||allStreams()[0];if(!s)return'<div class="empty">No streams loaded.</div>';selectedStream=s.id;const ps=d.subprocesses?.[s.id]||[],fs=streamFlows(s.id),m=streamMaturity(s.id);const tabs=['overview','inventory','asis','pain','requirements','team','tasks'];return `<div class="stream-selector">${allStreams().map(x=>`<button class="${x.id===s.id?'active':''}" data-open-stream="${x.id}"><b>${x.id}</b> · ${esc(x.name)}<span>${esc(x.bpo||'')}</span></button>`).join('')}</div><div class="stream-header"><div><h1>${s.id} · ${esc(s.name)}</h1><p class="small-note">${esc(s.source_status||'Cross-functional framework')}</p></div><div class="meta"><div class="meta-box"><div class="k">BPO</div><div class="v">${esc(s.bpo||'TBD')}</div></div><div class="meta-box"><div class="k">Readiness</div><div class="v">${fmtPct(m.readiness)}</div></div><div class="meta-box"><div class="k">As-Is maps</div><div class="v">${fs.length}</div></div></div></div><div class="tabs">${tabs.map(t=>`<button data-stream-tab="${t}" class="${streamTab===t?'active':''}">${({overview:'Overview',inventory:'Process Inventory',asis:'As-Is',pain:'Pain Points',requirements:'Requirements',team:'BPO / SMEs',tasks:'Tasks'})[t]}</button>`).join('')}</div>${streamTab==='overview'?streamOverview(s,ps,fs):streamTab==='inventory'?streamInventory(s,ps,fs):streamTab==='asis'?streamAsIs(s,ps,fs):streamTab==='pain'?streamPain(s):streamTab==='requirements'?streamRequirements(s):streamTab==='team'?streamTeam(s):streamTasks(s)}`}
function streamOverview(s,ps,fs){const d=data(),m=streamMaturity(s.id),raid=(d.raid||[]).filter(x=>x.stream===s.id&&!['Closed','Resolved'].includes(x.status)),dec=(d.decisions||[]).filter(x=>x.stream===s.id&&!['Closed','Decided'].includes(x.status));return `<div class="grid two-col"><div class="card pad"><h3>Transformation stage</h3><div class="stage-grid">${stageTile('As-Is',m.asis)}${stageTile('Ownership',m.ownership)}${stageTile('Requirements',m.requirements)}${stageTile('To-Be',m.tobe)}${stageTile('Fit/Gap',m.fitgap)}${stageTile('Data',m.data)}${stageTile('Testing',m.testing)}${stageTile('Readiness',m.readiness)}</div><div class="section-title"><h2>Enterprise L2 capabilities</h2><span>${(s.l2||[]).length}</span></div><div class="chip-row">${(s.l2||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div></div><div class="card pad"><h3>Workstream governance</h3><div class="grid two-col">${kpi('Pain points',(d.painPoints||[]).filter(x=>x.stream===s.id).length,'current state')}${kpi('Open RAID',raid.length,'risks / issues / dependencies')}${kpi('Open decisions',dec.length,'business decisions')}${kpi('Requirements',reqsFor(s.id).length,'traceability')}</div><div class="section-title"><h2>Imported current-state maps</h2><span>${ps.length}</span></div>${ps.slice(0,6).map(p=>`<button class="process-row" data-open-flow="${p.flowId}"><div><b>${esc(p.id)} · ${esc(p.name)}</b><small>${esc((p.systems||[]).join(' · '))}</small></div><span>${fmtPct(processGateScore(p))}</span></button>`).join('')||'<div class="empty">No dedicated current-state map in the supplied package.</div>'}</div></div>`}
function stageTile(label,v){return `<div class="stage-tile"><span>${esc(label)}</span><b>${fmtPct(v)}</b><div class="maturity-bar"><i style="width:${v}%"></i></div></div>`}
function streamInventory(s,ps,fs){return `<div class="page-head compact-head"><div><h2>Process Inventory</h2><p>L1 value stream → L2 enterprise capability → L3 current-state process → L4 activities.</p></div></div><div class="inventory-tree"><div class="card inventory-level l1"><span>L1</span><b>${esc(s.id)} · ${esc(s.name)}</b><small>Owner: ${esc(s.bpo||'TBD')}</small></div><div class="inventory-grid"><div class="card pad"><h3>L2 · Enterprise capabilities</h3>${(s.l2||[]).map((x,i)=>`<div class="inventory-row"><span>${s.id}.L2.${String(i+1).padStart(2,'0')}</span><b>${esc(x)}</b></div>`).join('')||'<div class="empty">No L2 capabilities loaded.</div>'}</div><div class="card pad"><h3>L3/L4 · Current-state maps</h3>${ps.map(p=>{const f=flowFor(p.flowId),score=processGateScore(p);return `<button class="inventory-process" data-open-flow="${p.flowId}"><div><span>L3 · ${esc(p.id)}</span><b>${esc(p.name)}</b><small>L4 activities: ${f?.nodes?.filter(n=>n.type==='activity').length||0} · Systems: ${(p.systems||[]).length}</small></div><div><strong>${fmtPct(score)}</strong><div class="maturity-bar"><i style="width:${score}%"></i></div></div></button>`}).join('')||'<div class="empty">No mapped L3 processes yet.</div>'}</div></div></div>`}
function streamAsIs(s,ps,fs){if(!fs.length)return `<div class="card empty">No Visio-derived As-Is flow is mapped to ${esc(s.id)} yet.</div>`;if(!selectedFlowId||!fs.some(f=>f.id===selectedFlowId))selectedFlowId=fs[0].id;const f=flowFor(selectedFlowId),p=ps.find(x=>x.flowId===f.id)||{};return `<div class="asis-toolbar"><select id="flowSelect">${fs.map(x=>`<option value="${x.id}" ${x.id===f.id?'selected':''}>${esc(x.legacyId?x.legacyId+' · ':'')}${esc(x.processName||x.title)}</option>`).join('')}</select><div><button class="btn ${asIsMode==='text'?'primary':''}" data-asis="text">Process text</button><button class="btn ${asIsMode==='flow'?'primary':''}" data-asis="flow">Flow chart</button></div><button class="btn" id="editProcess">Edit / validate process</button></div>${asIsMode==='flow'?flowEditorHtml(f):processText(p,f)}`}
function processText(p,f){const a=f.nodes.filter(n=>n.type==='activity'),score=processGateScore(p),g=p.gates||{};return `<div class="grid asis-grid"><div class="card pad"><div class="process-title-row"><div><h3>${esc(p.id||f.legacyId)} · ${esc(p.name||f.processName)}</h3><small>${esc(p.source||'Visio current-state map')}</small></div>${badge(p.status||f.status)}</div><div class="detail-grid"><label>Version<span>${esc(f.version||'')}</span></label><label>Maturity<span>${fmtPct(score)}</span></label><label>Systems<span>${esc((f.systems||[]).join(', ')||'—')}</span></label><label>Activities<span>${a.length}</span></label></div><div class="section-title"><h2>Activities</h2><span>click to document</span></div><ol class="activity-list">${a.map(n=>`<li data-edit-node="${n.id}"><b>${esc(n.label)}</b>${n.system?`<small>${esc(n.system)}${n.owner?' · '+esc(n.owner):''}${n.mode?' · '+esc(n.mode):''}</small>`:''}</li>`).join('')}</ol></div><div><div class="card pad"><h3>As-Is validation gate</h3><div class="maturity-bar large"><span style="width:${score}%"></span></div><strong class="maturity-number">${fmtPct(score)}</strong><div class="gate-list"><div class="gate-item done"><span>✓</span><b>Process map imported / documented</b></div>${PROCESS_GATES.map(([k,l])=>`<div class="gate-item ${g[k]?'done':''}"><span>${g[k]?'✓':'○'}</span><b>${esc(l)}</b></div>`).join('')}</div><button class="btn" id="editProcessGate">Update gate checklist</button></div><div class="card pad process-intel"><h3>Process intelligence</h3><div class="intelligence-grid">${kpi('Activities',a.length,'working view')}${kpi('Systems',(f.systems||[]).length,'identified')}${kpi('Connections',f.edges.length,'working view')}${kpi('Source nodes',f.sourceNodeCount||f.nodes.length,'Visio extraction')}</div>${f.simplifiedFromVisio?'<div class="notice warning">This detailed Visio was simplified into a connected editable working view. Source node and connector counts remain recorded for traceability.</div>':''}</div></div></div>`}
function flowEditorHtml(f){return `<div class="flow-tools"><button class="btn" id="addActivity">+ Activity</button><button class="btn" id="addDecisionNode">+ Decision</button><button class="btn" id="connectNode" ${selectedNodeId?'':'disabled'}>Connect from selected</button><button class="btn" id="editNode" ${selectedNodeId?'':'disabled'}>Document selected</button><button class="btn danger" id="deleteNode" ${selectedNodeId?'':'disabled'}>Delete selected</button><span>${f.nodes.length} nodes · ${f.edges.length} connectors</span></div><div class="flow-legend"><span class="manual-dot"></span>Manual / human <span class="auto-dot"></span>Automated / system <span class="decision-dot"></span>Decision</div><div class="flow-scroll"><div id="flowCanvas" class="flow-canvas"><svg class="flow-lines" viewBox="0 0 1200 720"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#7186a8"/></marker></defs>${f.edges.map(e=>edgeSvg(f,e)).join('')}</svg>${f.nodes.map(n=>`<div class="flow-node ${n.type||'activity'} ${String(n.mode||'').toLowerCase().includes('auto')?'automated':'manual'} ${n.id===selectedNodeId?'selected':''}" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><strong>${esc(n.label)}</strong>${n.system?`<small>${esc(n.system)}</small>`:''}${n.owner?`<em>${esc(n.owner)}</em>`:''}</div>`).join('')}</div></div>`}
function edgeSvg(f,e){const a=f.nodes.find(n=>n.id===e.from),b=f.nodes.find(n=>n.id===e.to);return a&&b?`<line x1="${a.x+72}" y1="${a.y+29}" x2="${b.x+72}" y2="${b.y+29}" marker-end="url(#arr)"/>`:''}
function streamPain(s){const d=data(),items=[...(d.painPoints||[]).filter(x=>x.stream===s.id).map(x=>({...x,_kind:'Pain point'})),...(d.opportunities||[]).filter(x=>x.stream===s.id).map(x=>({...x,_kind:'Opportunity'}))];return `<div class="section-title"><h2>Current-state issues & opportunities</h2><button class="btn primary" id="addPain">+ Add item</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Type</th><th>Process</th><th>Description</th><th>Impact</th><th>Phasing</th><th>Status</th></tr></thead><tbody>${items.map(x=>`<tr data-edit-pain="${x.id}" data-kind="${x._kind}"><td>${esc(x.id)}</td><td>${esc(x._kind)}</td><td>${esc(x.subprocess)}</td><td>${esc(x.title)}</td><td>${badge(x.impact)}</td><td>${esc(x.phase)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`}
function streamRequirements(s){const r=reqsFor(s.id);return `<div class="section-title"><h2>Requirements traceability</h2><button class="btn primary" id="addReq">+ Requirement</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Priority</th><th>Requirement</th><th>Pain point</th><th>D365 / Fit-Gap</th><th>Owner</th><th>Status</th></tr></thead><tbody>${r.map(x=>`<tr data-edit-req="${x.id}"><td>${esc(x.id)}</td><td>${badge(x.priority||'TBD')}</td><td><b>${esc(x.title)}</b>${x.acceptanceCriteria?`<small>${esc(x.acceptanceCriteria)}</small>`:''}</td><td>${esc(x.painPoint||'')}</td><td>${esc(x.d365Capability||'TBD')}<small>${esc(x.fitGap||'TBD')}</small></td><td>${esc(x.owner||'')}</td><td>${esc(x.status||'Draft')}</td></tr>`).join('')}</tbody></table>${r.length?'':'<div class="empty">No requirements entered yet. Use this register during current-state validation and design workshops.</div>'}</div>`}
function personResponsibilities(p){const d=data();return p.role==='BPO'?(d.bpoResponsibilities||[]):(d.smeTemplateResponsibilities||[])}
function personCard(p){const d=data(),rs=p.responsibilities||personResponsibilities(p),tasks=(d.tasks||[]).filter(t=>t.owner===p.name&&!['Closed','Approved'].includes(t.status)),over=tasks.filter(t=>(t.forecastDue||t.due)&&(t.forecastDue||t.due)<today()).length,dec=(d.decisions||[]).filter(x=>x.owner===p.name&&!['Closed','Decided'].includes(x.status)).length;return `<div class="card person-card" data-edit-person="${p.id}"><div class="role-tag">${esc(p.role)}</div><h3>${esc(p.name)}</h3><div class="role">${esc(p.stream)} · ${esc(allStreams().find(s=>s.id===p.stream)?.name||'')}</div><div class="person-metrics"><span><b>${tasks.length}</b> open tasks</span><span><b>${over}</b> overdue</span><span><b>${dec}</b> decisions</span></div><ul>${rs.slice(0,5).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="load"><span style="width:${Math.min(100,p.capacityPct||0)}%"></span></div><small>${p.capacityPct||0}% planned project capacity</small></div>`}
function streamTeam(s){const ps=(data().people||[]).filter(p=>p.stream===s.id);return `<div class="section-title"><h2>BPO & SME workspace</h2><button class="btn primary" id="addPerson">+ Add SME</button></div><div class="grid three-col">${ps.map(personCard).join('')||'<div class="card empty">No SMEs assigned yet.</div>'}</div>`}
function streamTasks(s){return taskTable((data().tasks||[]).filter(t=>t.stream===s.id),true)}
function renderPeople(){const d=data();return `<div class="page-head"><div><h1>People & Ownership</h1><p>BPO/SME accountability, workload and planned project capacity.</p></div><button class="btn primary" id="addPersonGlobal">+ SME</button></div><div class="grid three-col">${(d.people||[]).map(personCard).join('')}</div>`}
function taskTable(ts,compact=false){return `<div class="section-title"><h2>${compact?'Value-stream tasks':'Task Control Tower'}</h2><button class="btn primary" id="addTask">+ Task</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Type / Task</th><th>Stream</th><th>Owner</th><th>Priority</th><th>Progress</th><th>Status</th><th>Baseline</th><th>Forecast</th><th>Variance</th></tr></thead><tbody>${ts.map(t=>{const base=t.baselineDue||t.due||'',fc=t.forecastDue||t.due||'',v=base&&fc?Math.round((dateAt(fc)-dateAt(base))/86400000):0;return `<tr data-edit-task="${t.id}"><td>${esc(t.id)}</td><td><small>${esc(t.type||'Activity')}</small><b>${esc(t.title)}</b>${t.dependency?`<small>Depends: ${esc(t.dependency)}</small>`:''}</td><td>${esc(t.stream)}</td><td>${esc(t.owner)}</td><td>${badge(t.priority)}</td><td><div class="progress-cell"><span>${taskProgress(t)}%</span><div class="maturity-bar"><i style="width:${taskProgress(t)}%"></i></div></div></td><td><select class="status-select" data-task-status="${t.id}">${['Not Started','In Progress','Waiting','Blocked','Ready for Review','BPO Review','Approved','Closed'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td>${esc(base)}</td><td>${esc(fc)}</td><td>${v>0?`+${v}d`:v<0?`${v}d`:'—'}</td></tr>`}).join('')}</tbody></table></div>`}
function renderExecution(){const d=data(),ts=d.tasks||[],blocked=ts.filter(t=>t.status==='Blocked').length,over=ts.filter(t=>!['Closed','Approved'].includes(t.status)&&(t.forecastDue||t.due)&&(t.forecastDue||t.due)<today()).length;return `<div class="page-head"><div><h1>Execution Control</h1><p>Deliverables, dependencies, forecast dates and workstream execution.</p></div></div><div class="grid kpi">${kpi('Open tasks',ts.filter(t=>!['Closed','Approved'].includes(t.status)).length,'current workload')}${kpi('Overdue',over,'forecast date passed')}${kpi('Blocked',blocked,'requires intervention')}${kpi('Completed',ts.filter(t=>['Closed','Approved'].includes(t.status)).length,'approved / closed')}</div>${taskTable(ts)}<div class="section-title"><h2>Task Gantt</h2><span>forecast schedule</span></div>${gantt(ts.map(t=>({name:t.title,stream:t.stream,start:t.start,end:t.forecastDue||t.due,status:t.status})))}`}
